import './profile.scss';
import FacebookTwoToneIcon from '@mui/icons-material/FacebookTwoTone';
import LinkedInIcon from '@mui/icons-material/LinkedIn';
import InstagramIcon from '@mui/icons-material/Instagram';
import PinterestIcon from '@mui/icons-material/Pinterest';
import TwitterIcon from '@mui/icons-material/Twitter';
import PlaceIcon from '@mui/icons-material/Place';
import LanguageIcon from '@mui/icons-material/Language';
import EmailOutlinedIcon from '@mui/icons-material/EmailOutlined';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import Posts from '../../components/posts/Posts';
import { useParams } from 'react-router-dom';
import { useState, useEffect } from 'react';
import axios from 'axios';

const Profile = () => {
  const { id } = useParams();
  const [user, setUser] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchUser = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/users/${id}`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`,
          },
        });
        setUser(res.data);
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to load user');
      }
    };
    fetchUser();
  }, [id]);

  if (error) return <div>Error: {error}</div>;
  if (!user) return <div>Loading...</div>;

  return (
    <div className="profile">
      <div className="images">
        <img src={user.coverPic || 'https://images.pexels.com/photos/13440765/pexels-photo-13440765.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=2'} alt="" className="cover" />
        <img src={user.profilePic || 'https://images.pexels.com/photos/14028501/pexels-photo-14028501.jpeg?auto=compress&cs=tinysrgb&w=1600&lazy=load'} alt="" className="profilePic" />
      </div>
      <div className="profileContainer">
        <div className="uInfo">
          <div className="left">
            {user.socialLinks?.facebook && (
              <a href={user.socialLinks.facebook} target="_blank" rel="noopener noreferrer">
                <FacebookTwoToneIcon fontSize="large" />
              </a>
            )}
            {user.socialLinks?.instagram && (
              <a href={user.socialLinks.instagram} target="_blank" rel="noopener noreferrer">
                <InstagramIcon fontSize="large" />
              </a>
            )}
            {user.socialLinks?.twitter && (
              <a href={user.socialLinks.twitter} target="_blank" rel="noopener noreferrer">
                <TwitterIcon fontSize="large" />
              </a>
            )}
            {user.socialLinks?.linkedin && (
              <a href={user.socialLinks.linkedin} target="_blank" rel="noopener noreferrer">
                <LinkedInIcon fontSize="large" />
              </a>
            )}
            {user.socialLinks?.pinterest && (
              <a href={user.socialLinks.pinterest} target="_blank" rel="noopener noreferrer">
                <PinterestIcon fontSize="large" />
              </a>
            )}
          </div>
          <div className="center">
            <span>{user.name}</span>
            <div className="info">
              {user.location && (
                <div className="item">
                  <PlaceIcon />
                  <span>{user.location}</span>
                </div>
              )}
              {user.website && (
                <div className="item">
                  <LanguageIcon />
                  <span>{user.website}</span>
                </div>
              )}
            </div>
            <button>Follow</button>
          </div>
          <div className="right">
            <EmailOutlinedIcon />
            <MoreVertIcon />
          </div>
        </div>
        <Posts userId={id} />
      </div>
    </div>
  );
};

export default Profile;
